import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from counters_meta import SYN, ARCH, SWAP_RULES, PATCH


def build():
    ids = set(HEROES)
    out = {h: {'strong_vs': {}, 'weak_vs': {}} for h in sorted(ids)}
    for a, b, why in M:
        assert a in ids and b in ids and a != b, (a, b)
        out[a]['strong_vs'].setdefault(b, why)
        out[b]['weak_vs'].setdefault(a, why)
    for a in out:
        for b in out[a]['strong_vs']:
            if b in out[a]['weak_vs']:
                print('CONFLICT', a, b)
    for h in SYN:
        assert h in ids and all(x in ids for x in SYN[h]), h
    for k in ARCH:
        assert all(x in ids for x in ARCH[k]), k
    for h, st in STATS.items():
        assert h in ids and all(x in ids for x in st['by']) and all(x in ids for x in st['vs']), h
    missing = [h for h in ids if not out[h]['strong_vs'] or not out[h]['weak_vs']]
    src = [{'id': k, 'url': v[0], 'used_for': v[1]} for k, v in S.items()]
    src.append({'id': 'jeuvideo', 'url': 'https://jeu.video/en/guide/overwatch-2-counters-objective',
                'used_for': 'Swap after the same threat stops you two fights running'})
    data = {
        'as_of': '2026-11-14',
        'patch': 'Season 5 "A Grim Doctrine" midseason (2026-11-03 patch, 2026-11-05 hotfix); 5v5 role queue',
        'sources': src,
        'note': ('Reasons are mechanics. A tag like [2026-11-03] marks a reason that depends on a 2025-2026 change. '
                 'stat_counter_ratings are counterwatch.gg counter ratings (duel/teamfight edge with hero strength removed, all ranks, all game types, '
                 'page data 2026-11-14). Hero 55 (Hudson) is announced for Season 6 and not released, so not covered.'),
        'heroes': {h: {'name': n, 'role': r, 'subrole': sr} for h, (n, r, sr) in sorted(HEROES.items())},
        'matchups': out,
        'stat_counter_ratings': {h: {'countered_by': STATS[h]['by'], 'counters': STATS[h]['vs']} for h in sorted(STATS)},
        'synergies': {h: SYN[h] for h in sorted(SYN)},
        'archetypes': ARCH,
        'swap_rules': [r['rule'] for r in SWAP_RULES],
        'swap_rule_sources': [{'rule': r['rule'], 'url': S[r['src']][0] if 'src' in r else r['url']} for r in SWAP_RULES],
        'patch_flags': {h: PATCH[h] for h in sorted(PATCH)},
    }
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w', encoding='utf8') as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    n = sum(len(v['strong_vs']) for v in out.values())
    print('heroes', len(out), 'pairs', n, 'stat heroes', len(STATS), 'missing side', missing)


if __name__ == '__main__':
    build()

